-- Generated by `fledge settings apply` from ~/.config/mbm/settings.json over the
-- shipped defaults. Do not edit: change settings (or the defaults) instead.

-- Each bind runs on its own: one that Hyprland refuses (a dispatcher renamed
-- in a new release, say) is listed in one notification at the end instead of
-- taking every bind after it down too.
local failed = {}
local function try(keys, fn)
  local ok, err = pcall(fn)
  if not ok then failed[#failed + 1] = keys .. " (" .. tostring(err) .. ")" end
end

try("SUPER + RETURN", function() hl.bind("SUPER + RETURN", hl.dsp.exec_cmd("uwsm app -- $TERMINAL"), { description = "Terminal" }) end)
try("XF86AudioRaiseVolume", function() hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("qs -c mbm ipc call osd volume +5"), { description = "Volume up", locked = true, repeating = true }) end)
try("SUPER + SPACE", function() hl.bind("SUPER + SPACE", hl.dsp.exec_cmd("qs -c mbm ipc call launcher toggle"), { description = "Launcher" }) end)
try("ALT + TAB", function() hl.bind("ALT + TAB", function() hl.dispatch(hl.dsp.window.cycle_next()) hl.dispatch(hl.dsp.window.bring_to_top()) end, { description = "Focus on next window" }) end)
try("SUPER + mouse:273", function() hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { description = "Resize window" }) end)
try("SUPER + code:10", function() hl.bind("SUPER + code:10", hl.dsp.focus({ workspace = 1 }), { description = "Switch to workspace 1" }) end)

-- Key recording in the settings window: an empty submap, so every key reaches
-- the window. SUPER+CTRL+ALT+Escape always gets out (e.g. if the shell died).
try("mbm-record submap", function() hl.define_submap("mbm-record", function() hl.bind("SUPER + CTRL + ALT + Escape", hl.dsp.submap("reset")) end) end)

if #failed > 0 then
  local text = "fledge: binds.lua: these binds didn't load: " .. table.concat(failed, "; ")
  io.stderr:write(text, "\n")
  pcall(function()
    hl.notification.create({ text = text, timeout = 15000, icon = "error", color = "rgb(ff5555)" })
  end)
end
